typedef float rational_t;

class vector3d
{
public:
  rational_t x, y, z;
  vector3d& operator+=(const vector3d& b)
  {
    x += b.x; y += b.y; z += b.z;
    return *this;
  }
};

extern const vector3d ZEROVEC;

class po
{
  float m[4][4];
public:
  const vector3d& get_position() const { return (const vector3d&)m[3]; }
  vector3d non_affine_inverse_scaled_xform(const vector3d& v) const;
};

class entity;
class link_interface
{
  char base[8];
  entity* my_parent;
public:
  entity* get_parent() const { return my_parent; }
};

class entity
{
public:
  struct movement_info
  {
    bool frame_delta_valid;
    bool last_frame_delta_valid;
    char pad[62];
    po frame_delta;
  };
private:
  char prefix0[16];
  po my_po;
  char prefix1[24];
  link_interface* link;
  char prefix2[228];
  movement_info* mi;
public:
  const po& get_rel_po() const { return my_po; }
  link_interface* link_ifc() const { return link; }
  bool has_parent() const { return link_ifc() && link_ifc()->get_parent(); }
  vector3d get_frame_abs_delta_position(bool first_time, const vector3d& rel_delta_pos) const;
};

vector3d entity::get_frame_abs_delta_position(bool first_time, const vector3d& rel_delta_pos) const
{
  vector3d deltapos=ZEROVEC;
  if (!first_time)
  {
    deltapos = get_rel_po().non_affine_inverse_scaled_xform(rel_delta_pos);
  }
  if (mi && mi->frame_delta_valid)
    deltapos += mi->frame_delta.get_position();
  else
    deltapos += ZEROVEC;
  if (has_parent())
  {
    deltapos = ((entity *)link_ifc()->get_parent())->get_frame_abs_delta_position(false,deltapos);
  }
  return deltapos;
}
